add('WI01',I,11,52,'Interpreter construction and binding',['Depth100 passes the depth gate.','Depth greater than100 requests a diagnostic and exits.','Clear removes waits, child, branch/button/choice state and follower overrides.','Setup binds the supplied map or, if omitted, the current map.','Setup stores the event number and list, starts index0 and clears branch state.'],[C+':117',CE+':40–54',E+':288–290',FF+':38–45'],[main+':19,89,94',cm+':40'])
add('WI02',I,54,82,'Starting-event priority',['A pending map refresh is consumed first.','Reserved positive common-event ID takes priority and is cleared after setup.','The first starting current-map event in iteration order takes next priority.','Only trigger below3 is locked and its starting flag cleared at this entrance.','Setup for that map event uses its actual map identity.','Autorun common events are considered only after reserved/map events.','Autorun common trigger1 reads the ordinary switch slot, not a script-named expression.','Running means the list is non-nil.'],[S+'003_Game processing/002_Scene_Map.rb:167',SYS+':279–285'],[main+':54,88,98,114',cm+':12'])
add('WI03',I,84,136,'Update ordering and yields',['Every update initializes the loop counter to0.','Iteration101 first requests Graphics update then resets count if the request returns.','Graphics failure occurs before reset and before the subsequent checks/dispatch; this guard does not poll input.','Disconnected current/bound maps clear only event number to0.','A child updates before parent waits and parent dispatch; parent yields while child remains running.','Message waiting yields.','A set route-wait flag checks player, current-map events and all followers; any forced route yields.','Only when all those routes end is that wait cleared.','Ending-surf state yields.','Positive wait count compares monotonic elapsed time and resets wait fields only once due.','Queued menu opening yields.','An idle main interpreter chooses a starting event; idle non-main returns.','Only strict false dispatch result yields without outer index increment.','Every other normal result advances the outer index and loops.','Command end can be followed by an additional empty-list iteration that contributes to the guard count.'],[C+':105/106/116/117/201/209/210/351/355',S+'003_Game processing/002_Scene_Map.rb:165–175'],[main+':80–98',cm+':12–17'])
add('WI04',I,138,206,'Script and ordinary character context',['A normal script returns its expression value.','SystemExit and class-named Reset are rethrown.','Other exceptions become an event-script error carrying context; not a success result.','Player selection−1 returns the player.','Self0 and positive/specific IDs query the current-map event collection.','Those ordinary character lookups do not query the bound map or automatically target a follower.'],[C+':111/122/202/207/209/355'],[main+':94–107',cm+':16,19,33,59,64,66,120'])
add('WI05',I,208,267,'Global locks and message logical lookahead',['Global lock mini-locks current-map events; unlock requests all current-map unlocks.','Message lookahead skips labels and comment commands.','Forward label targets can move the lookahead; backward targets do not repeat it.','Break-loop lookahead scans until a lower-indent repeat or terminal boundary.','The separate repeat-above lookahead helper reads an undefined indent in the finite legal four-command layout.','That failure precedes message waiting and text display; main413 uses another path.'],[C+':101',I+':426–438'],[cm+':124–126',main+':139'])
add('WI06',I,269,329,'Follower one-shot overrides, picture helper, erase and common helpers',['Follower move/animation overrides store the requested name or first-follower choice.','Clear/end removes both overrides.','Picture helper selects a separate battle slot by adding50.','Record-style erase requires the current-map event to exist, erases first and only then optionally records; its own index advances on normal return even if absent.','Interpreter direct common helper skips missing records with nil return; negative IDs follow array lookup.','Nonbattle direct helper drives graphics/input/interpreter/map-mini updates to completion and returns nil.','Battle direct helper instead sets the battle interpreter.','Default script self-switch uses bound-map identity and requests refresh only for changed value and a loaded map.'],[C+':207/209/355',S+'012_Overworld/005_Overworld_Fishing.rb',MD+':154–157'],[main+':63–66,94–100',cm+':120'])
add('WI07',I,332,383,'Private variables and wall-clock event time',['Temporary-switch helpers use ordinary self lookup and thus require its receiver.','No-argument variable lookup uses bound-map/event private key and returns nil when store absent.','One-argument variable assignment lazily creates the private store and writes the bound key.','Global variable assignment requests current-map refresh.','Event-time recording samples one integer wall-clock time for all requested event IDs.','Each event is processed in order, bound-map persistent A first and private timestamp next.','Already-true persistent A still allows timestamp overwrite without a new changed-value refresh.','Later failure does not undo the prior completed prefix.'],[E+':88–126',MD+':36,91',S+'002_Save data/004_Game_SaveValues.rb:76–81'],[main+':37–39,94',cm+':19'])
add('WI08',I,385,438,'Push and trainer wrappers',['Push first applies strict directional permission; rejection precedes counter/record.','Passing strict precheck increments push count before the ordinary movement attempt.','A record is attempted after movement even if position did not change.','Only a changed position requests optional push audio, locks player, waits for movement and unlocks on normal completion.','The strength wrapper skips push when strength is inactive and normally returns true.','Smash helper calls the field removal if self exists, then advances its own command position even if absent.','Trainer intro debug bypass applies only to an unregistered type; otherwise resolves type, global-locks then requests intro music.','Trainer end unlocks current map then erases self route when a receiver exists.'],[MD+':159–163',S+'012_Overworld/004_Overworld_FieldMoves.rb:213–227',S+'019_Utilities/003_Utilities_BattleAudio.rb:63'],[main+':66',F+'wp59-world-time-weather-field-moves.md / parent ownership'])
add('WI09',I,440,454,'Temporary shop price override',['Item identity is resolved before price writes.','An absent temporary pair is initialized with unset sentinels.','Only a positive buy price overwrites the buy slot.','A nonnegative sell price writes its doubled representation; otherwise positive buy supplies the selling representation.','Sell-price helper supplies no buy override.'],[S+'016_UI/020_UI_PokeMart.rb:68–87',S+'016_UI/021_UI_BattlePointShop.rb:68–75'],['WP65 / UI shop primary; WI-SHOP-01 OPEN'])
add('WI10',E,9,54,'Event construction and start/erase',['ASCII case-insensitive size(w,h) decimal substring changes default occupied width/height.','Original map/event identity and original coordinate anchor are retained.','Temporary switches start empty and erased/start/route-erased flags start false.','Start only flags a list with more than one entry.','Ordinary erase marks erased then refreshes, without registering a saved erase record.','Erase-route marks route erased then refreshes.'],[MP+':45–74',FL+':7–28'],[main+':15,28–35,62',rm+':23'])
add('WI11',E,56,131,'Event-local state and cooldowns',['Temporary ON means strict true; OFF accepts absent/false.','Temporary switch writes refresh the event.','Page script switch uses expression truthiness; ordinary switch name absent is false.','Event private variable key uses original bound map/event; direct event setter does not lazily create the store.','Seconds expiry requires an existing timestamp and strict now>record+duration, default86400.','Day expiry integer-converts missing timestamp to0 and applies floor-days plus strict remainder/local-seconds comparison.','Clock rollback follows that same expression without a zero clamp.','Cooldown true additionally requires temporary A OFF; otherwise returns false and marks event refresh.','Cooldown does not delete the private time record.','on-event requires original event map equal current map and the player inside occupied tiles.'],[I+':332–382',S+'012_Overworld/003_Overworld_Time.rb:4–6'],[main+':31,37–39,98',cm+':33'])
add('WI12',E,133,195,'Over-trigger and NPC trigger entrances',['Named graphic with non-through fails over-trigger.','Any hiddenitem name fails over-trigger.','Otherwise any passable occupied tile permits over-trigger.','NPC failed-move touch requires trigger2, idle main, direction-aligned adjacent coordinate, non-jump and non-over-trigger.','Turn-completed sensing additionally requires not already starting and sight/trainer exact ASCII pattern; checks reachability.','Move-completed sensing accepts sight/trainer with reachability or counter with facing-range only.','Counter is absent from turn-only sensing.','Auto touch uses co-location/non-jump/over-trigger; autorun trigger3 calls start.'],[CH+':553–565,815–821',P+':332–412,543–554',OW+':340–392'],[main+':21,45–50,150',cm+':66'])
add('WI13',E,197,258,'Page selection and mutation',['Scan pages last to first; both enabled switches, variable threshold and strict-true self switch must pass.','An erased event selects no page.','Same selected page returns before reapplying content.','No page clears graphic/list/parallel interpreter, sets through and no trigger; it does not clear forcing.','A different valid page sets graphic/hue regardless of direction/pattern comparisons.','Direction changes only when saved original differs; then both current/original change and prelock clears even when direction-fixed.','Pattern independently changes only when saved original differs.','A valid new page reinstalls route/index, clears forcing and replaces parallel interpreter only for trigger4.','It then checks auto-trigger.'],[MP+':429–437',C+':116',CH+':521–535'],[main+':28–35',rm+':23,27'])
add('WI14',E,260,302,'Event update eligibility and parallel lifecycle',['Previous successful-update flag has first priority in eligibility recomputation.','Autorun/parallel, forcing/moveto and update name precede screen buffer checks.','Every update computes eligibility before clearing previous flag and sets it again only if permitted.','Thus an already-successful same instance continuously called stays eligible off screen.','A denied update stores false and returns.','A permitted update calls character update, senses movement completion, consumes own refresh and auto-trigger.','Idle parallel interpreter is set up with explicit original event map/event and updated.','Completed nontransparent graphic jumps request landing dust via current scene spriteset.'],[MP+':439–465',S+'005_Sprites/006_Spriteset_Global.rb',SYS+':279–285'],[main+':52,84,148'])
add('WI15',CE,8,56,'Common parallel event lifecycle',['Metadata getters use common-event record.','Script-named switch returns expression raw value; refresh uses truthiness.','Only trigger2 and enabled switch preserve/create a parallel interpreter; otherwise destroy it.','Update does nothing when no interpreter.','An idle common interpreter binds event0 and current default map before each run.','Update does not unconditionally reevaluate the script expression.'],[MP+':67–70,429–465'],[main+':18,98,108',cm+':40'])
add('WI16',FF,4,85,'Saved follower record and runtime rebuilding',['Saved follower record separates original/current identity, position/direction, appearance, name/common event and visibility.','Default visible true and post-transfer hidden false combine conjunctively for visibility.','Interaction requires event, list length>1 and configured common event; then refresh current map, lock follower and setup main with follower map/id.','Global follower array lazily defaults empty and is persistent.','Temporary follower factory lazily builds runtime objects from saved records; these objects are session state.'],[FL+':7–28',S+'002_Save data/004_Game_SaveValues.rb:76–81',S+'005_Sprites/006_Spriteset_Global.rb:7–17'],[main+':94–96,155–167'])
add('WI17',FF,89,151,'Follower add/remove/get',['Missing add receiver returns.','Duplicate original=current-map/event ID returns before data/object insertion.','New add captures current-map identity and clones appearance before construction and paired insertions.','Event removal requires saved current map equal current, original map equal event map and matching event ID.','Name removal deletes all matching records and runtime slots then compacts both.','Clear empties both and increments sprite-refresh revision.','Index lookup matches enumeration index; name lookup returns first match.','Paired iteration uses saved list positions to retrieve runtime objects.'],[S+'005_Sprites/006_Spriteset_Global.rb:34',FF+':321–335'],[main+':155–157'])
add('WI18',FL,7,47,'Follower reconstruction and through movement',['Reconstruction makes an event from saved coordinates/id/name and optionally obtains configured common list immediately.','Original-map identity and current-map receiver are distinct in reconstructed follower.','Saved appearance and cardinal direction are applied after ordinary event setup.','A through step saves old through, sets true, performs one cardinal attempt and restores old value only on normal return.'],[FF+':79–104,294–296'],[main+':157,167'])
add('WI19',FL,48,111,'Follower conditional displacement',['One-step fancy move is allowed by target=player coordinate, target entry passability or unpassable origin.','Two-axis-equal distance1 chooses cardinal step.','Axis distance2 first checks middle entry, then landing entry, then origin exit.','Middle passable makes two one-step attempts, without a guarantee the second reaches.','Middle blocked/landing passable/origin passable attempts jump and chooses leader jump or move speed; walking leader halves jump duration.','Origin blocked instead makes two through steps.','Both middle/landing blocked makes no movement.','Any other non-coincident target directly moveto, including(1,1) and same-axis distance≥3.'],[FL+':134–168',P+':423–427'],[main+':158–163'])
add('WI20',FL,115,168,'Follower target and map transition',['Forced route skips following before end-movement normalization.','A follow attempt snaps current motion to tile modulo map size and clears move/jump state.','Connected target is one tile behind leader; ledge behind extends once further; absent facing target falls back leader position.','Unconnected target is leader position.','Changing target map computes relative vector and uses it for coordinates before target displacement.','Instant/unconnected follows moveto; otherwise conditional fancy displacement.'],[FF+':165–175,178–191',MF+':221–327'],[main+':158–164'])
add('WI21',FL,174,215,'Follower location receiver',['Requires a valid coordinate before through shortcut.','Tile-event blockers skip through/ignored terrain/disabled bridges.','Ledge or banned entry direction rejects.','Active bridge or priority0 can finish tile-event layer.','Map layers scan top down, skip empty/ignored/disabled bridge, reject ledge/entry ban and stop at bridge/priority0.','A non-through named graphic event at the coordinate rejects at collision layer; tile permission is not final permission.'],[FL+':48–89'],['WP12 layer5 / WI-TERRAIN-01 reception',main+':162'])
add('WI22',FF,155,191,'Follow writes and explicit transfer',['Turn chain is player then previous follower, writing each saved direction.','Move chain follows player then previous follower and writes x/y/current map/direction after each normal call.','Explicit transfer puts all runtime followers on current player/current map, sets player direction and opacity255.','Transfer writes saved x/y/map/direction and sets post-transfer hidden.'],[P+':424–427,547',S+'003_Game processing/002_Scene_Map.rb:89'],[main+':158–164,167'])
add('WI23',FF,193,238,'Door operation family',['Door entry snapshots player and all follower positions before installing any route.','Each follower adds at most one axis command, horizontal priority, prepended to cumulative route based on snapshots.','Each receives cumulative route then opacity0.','Hide only writes runtime opacity0.','Put-on-player writes runtime position/opacity255, saved x/y and post-transfer hidden; does not itself rewrite saved map/direction.'],[S+'021_Compiler/004_Compiler_MapsAndEvents.rb:815–903',OW+':489–524'],[main+':172–177'])
add('WI24',FF,242,297,'Follower update and interaction',['Menu returns before all follower updates.','Empty saved list returns.','A moving/jumping player clears post-transfer hidden and turns follower toward the player.','Each follower takes predecessor speed and transparency from saved visibility.','Ice sliding straightens and disables walk animation; other state enables it.','Moving/jumping follower or nonmoving player directly updates follower; otherwise a not-starting follower is temporarily marked starting for its update.','Only saved direction is written by this per-frame loop.','USE interaction requires no menu/battle/player-forcing/message/main-interpreter and a facing-tile co-located nonjumping follower.','All matching followers are visited; no unconditional first-match break.'],[P+':427',FL+':134–168',FF+':38–45'],[main+':163–165'])
add('WI25',FF,302,390,'Follower sprite and public helper lifecycle',['Sprite refresh disposes old sprites and creates one character sprite per follower.','Revision changes trigger refresh on next sprite update.','Dispose is idempotent.','Public add/get/remove helpers delegate saved/runtime pairing; nil name gets first follower.','Public clear removes followers before attempting partner deregistration and rescues that latter call.','Door helpers delegate directly.'],[S+'005_Sprites/006_Spriteset_Global.rb:7–34',OW+':649–651'],[main+':155–177','WP16 sprite/display interface'])
add('WI26',CH,362,400,'Forced-route install and moveto',['The first takeover saves original route/index only when original route slot is nil.','A later forced route preserves an already-nonnil saved original.','Install sets index0/forcing, clears prelock and old wait, then synchronously attempts processing.','Moving/jumping attempt returns early; a static state command can commit before209 returns.','Moveto wraps x/y by map size, writes real coordinates, marks moved-to, clears prelock, recomputes bush depth and conditionally emits leave-tile.','Only an existing changed previous tile emits leave notification; old tile bookkeeping advances after notification returns.'],[C+':209/202',FL+':91–168',P+':262–266'],[rm+':23',main+':142'])
add('WI27',CH,427,551,'Route dispatch flow',['Moving/jumping returns before route read.','List length≤1 returns before end recovery.','The iteration cap is total length−1, allowing repeating routes to wrap.','Nonrepeat terminator restores original route/index and clears forcing if forced, resets stop time and returns.','Movement1–14 always ends processing after attempt; index advances only for skippable or current moving/jumping state.','Wait/turn15–26 always advance and end processing.','State27+ normally advances without returning, permitting same-call chaining.','Script is evaluated before literal any-line prefix checks.','Any of three exact line-start prefixes forces advance+return on normal evaluation, even longer suffix names; whitespace/receiver prefix prevents a match.','Script failure occurs before prefix/index update.'],[C+':209/210',P+':121–193',OW+':489–524'],[rm+':9–25,33–78'])
add('WI28',CH,145,185,'Autonomous frequency and locks',['Frequency1–6 delays are4.75/3.6/2.55/1.6/.75/0seconds.','Same frequency assignment returns without rewrite.','Lock mini-lock use locked state; full lock turns to player, prelock0.','Unlock clears locked and restores a nonzero prelock direction only if direction is not fixed.'],[I+':208–216',CH+':912–997'],[main+':54,148',rm+':25'])
add('WI29',CH,893,1023,'Character scheduling, motion and animation',['Menu returns before clock handling.','Backward/missing monotonic timestamp resets reference; time increment>.25 returns before movement/route.','Update commands happen before movement then animation.','Positive route wait blocks route commands until monotonic threshold.','Forcing bypasses autonomous lock/starting/frequency conditions.','Autonomous actions require not starting/locked/moving/jumping and enough stopped time.','Movement/jump completion emits general step event before subsequent bush/stop flags.','Animation start/end and walking/stepping/lock-pattern gates are distinct from logical displacement.'],[E+':274–301',P+':416–554'],[main+':148',rm+':17,23–25'])
add('WI30',P,202,412,'Player event target entrances',['Facing-event uses current map, may bypass main-running guard only with explicit ignore flag, excludes jumping/over-trigger and optionally looks one beyond counter.','Here-trigger loops all matching co-located trigger IDs and requires over-trigger.','There-trigger requires valid facing coordinate and non-over-trigger; counter extension happens only if no first trigger succeeded.','Player blocked-touch accepts1/2 then sensing/counter-specific guards.','Distance checks use trainer/sight reachability or counter facing-range and honor main-running check.'],[S+'003_Game processing/002_Scene_Map.rb:214–227',P+':543–554'],[main+':45–48'])
add('WI31',SYS,274,287,'Timer and SPECIAL skip consumer',['Timer returns0 without start or stats, otherwise raw initial minus elapsed game time without zero clamp.','System SPECIAL checks comment context while main interpreter is running.','Successful skip writes bound-map persistent A, ends current interpreter then requests start on captured current event.','Normal system/mini calls can reach it; there is no input-consumption reset by this handler.'],[S+'007_Objects and windows/011_Messages.rb:25–50',S+'003_Game processing/002_Scene_Map.rb:121–134,165–229'],[main+':110–128',cm+':46'])
add('WI32',S+'007_Objects and windows/011_Messages.rb',4,50,'Map miniupdate and exact comments',['Map update helper only calls miniupdate in a nonfaded map scene.','Comment input requires an array list and exact text on108/408, returns at most requested following parameters.','A matched end comment returns an empty array, distinct from nil.','Current-event comment additionally requires running main and current self receiver.'],[SYS+':279–285',I+':304–319',C+':105'],[main+':112–128'])
add('WI33',OW,440,524,'System route wrapper vs compiled route',['Runtime wrapper builds nonrepeat/skippable route with throughON before requested items and OFF before terminal.','It does not preserve previous through value.','One/two/four-parameter commands are consumed by arity; asynchronous script adds WAIT0.','waitComplete input is unused; helper returns the route after optional install, without waiting.','Compiled generation has the parameter/ASYNC/terminal behavior but no unconditional through envelope.','Compiler push-and-wait emits209 and separately210, including door paths.'],[S+'021_Compiler/004_Compiler_MapsAndEvents.rb:88–144,815–903'],[main+':174–177',rm+':7,17'])
add('WI34',S+'003_Game processing/001_StartGame.rb',39,104,'Saved event state load boundary',['New game clears old start flags/common reservation and main context before new values/map setup.','Load first loads all values then load-map, autoplay, map update and conditional map-record restore.','Mismatch/safesave rebuild clears main list when running and reuses same factory setup.','Normal nonrebuild branch still sends enter notification.','Enter-map first registered consumer may clear local map records before later restore.','Runtime map instances can survive reuse while rebuilt instances reset; saved record persistence alone does not imply later restoration.'],[OW+':224–238',MD+':144–182',S+'002_Save data/004_Game_SaveValues.rb:19–87'],[main+':68',F+'wp11-map-topology-transfer.md / WI-SAVE-01'])
add('WI35',S+'003_Game processing/002_Scene_Map.rb',72,230,'Transfer, menu and update consumer',['201 normal and mini consumers pass cancel-swimming false.','Transfer moves player, aligns direction, straightens then transfers follower runtime/saved data before map update/spriteset rebuild.','Normal scene drives main interpreter before player/maps/system/screen; mini excludes main interpreter and normal end-key dispatch.','Menu call sets in-menu before map update and resets it only after pause menu normally returns.','Map update skips ordinary map events in-menu but still updates common events.','End-key registration and queued consumption are different gates; messaging returns before both.','SPECIAL skip in system can leave the same trigger available for normal end-key registration.'],[MP+':439–465',SYS+':279–285'],[main+':52,112,126',rm+':21'])
add('WI36',MD,144,183,'Map local record consumers',['Clear empties erased/moved maps and local effects.','Erase record uses current-map/event key.','Moved record requires integer ID and current event then captures coordinates/direction/through, replacing same key.','Restore erases only matching-map true records.','Moved matching-map record skips missing event, moves then requests only cardinal direction.','Through true write occurs outside map-match branch; false does not clear existing true.','An absent receiver in that outside true write can fail after earlier completed records; no rollback.'],[I+':294–300,385–412',S+'003_Game processing/001_StartGame.rb:70–71'],[main+':66–72',F+'wp11-map-topology-transfer.md'])
